SELECT * FROM product_all 
WHERE seller_id = #{sellerId} 
ORDER BY product_reg_date DESC

/* product 대신 실제 존재하는 product_all 테이블 사용 */
SELECT * FROM product_all


        AND product_category = #{category}



        AND product_name LIKE CONCAT('%', #{search}, '%')


ORDER BY product_reg_date DESC
